23	func DetectJPEG(blob []byte) *Detection {
24		if len(blob) < 16 || !bytes.HasPrefix(blob, []byte{0xFF, 0xD8}) {
25			return nil
26		}
27	
28		text := string(blob[:min(len(blob), maxMetadataScanBytes)])
29		if !motionPhotoMarkerRegex.MatchString(text) {
30			return nil
31		}
32	
33		videoStart := detectVideoStart(blob, text)
34		if videoStart < 0 || videoStart >= len(blob) {
35			return nil
36		}
37	
38		return &Detection{
39			VideoStart:              videoStart,
40			PresentationTimestampUs: parsePresentationTimestampUs(text),
41		}
42	}
