44	func ExtractVideo(blob []byte) ([]byte, *Detection) {
45		detection := DetectJPEG(blob)
46		if detection == nil {
47			return nil, nil
48		}
49	
50		videoBlob := blob[detection.VideoStart:]
51		if !looksLikeMP4(videoBlob) {
