58	func detectVideoStart(blob []byte, text string) int {
59		if matches := microVideoOffsetRegex.FindStringSubmatch(text); len(matches) == 2 {
60			if offset, err := strconv.Atoi(matches[1]); err == nil && offset > 0 && offset < len(blob) {
61				start := len(blob) - offset
62				if looksLikeMP4(blob[start:]) {
63					return start
64				}
65			}
66		}
67	
68		return findEmbeddedMP4Start(blob)
69	}
