71	func parsePresentationTimestampUs(text string) int64 {
72		matches := presentationRegex.FindStringSubmatch(text)
73		if len(matches) != 2 {
74			return 0
75		}
76	
77		value, err := strconv.ParseInt(matches[1], 10, 64)
78		if err != nil {
79			return 0
80		}
81		return value
82	}
