84	func findEmbeddedMP4Start(blob []byte) int {
85		searchFrom := len(blob)
86		for searchFrom > 8 {
87			index := bytes.LastIndex(blob[:searchFrom], []byte("ftyp"))
88			if index < 4 {
89				return -1
90			}
91	
92			start := index - 4
93			if looksLikeMP4(blob[start:]) {
94				return start
95			}
96	
97			searchFrom = index - 1
98		}
99	
100		return -1
101	}
102	
103	func looksLikeMP4(blob []byte) bool {
104		if len(blob) < 12 || !bytes.Equal(blob[4:8], []byte("ftyp")) {
105			return false
106		}
107	
108		size := binary.BigEndian.Uint32(blob[:4])
109		return size == 1 || size >= 8
110	}
